/** Compare snapshots generated by native-integration-initial-snapshot.mjs in two checkouts. */
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
const [before,after]=process.argv.slice(2);if(!before||!after)throw Error('Usage: node tests/native-integration-initial-compare.mjs master.json candidate.json');
const a=JSON.parse(await readFile(before)),b=JSON.parse(await readFile(after));
assert.equal(a.length,30);assert.equal(b.length,30);for(let i=0;i<30;i++){assert.equal(a[i].id,i+1);assert.deepEqual(b[i],a[i],`initial stage ${i+1} changed`)}
console.log('PASS 30 initial Engine state snapshots: units, terrain, water, zones, active/phase/side; not gameplay acceptance');
